impl Document {
    pub(crate) fn compare_diagnostic_access_permission(
        &self,
        other: &Document,
        a: &DiagnosticAccessPermission,
        b: &DiagnosticAccessPermission,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_common_element(other, a.base(), b.base(), path)?;
        if a.get_authentication_enabled() != b.get_authentication_enabled() {
            return Err(format!("{path}: AUTHENTICATION_ENABLED mismatch"));
        }
        let list_a = a.get_diagnostic_session_refs();
        let list_b = b.get_diagnostic_session_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DIAGNOSTIC_SESSION_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.DIAGNOSTIC_SESSION_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.DIAGNOSTIC_SESSION_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.DIAGNOSTIC_SESSION_REFS[{index}]"),
            )?;
        }
        if a.get_environmental_condition_ref() != b.get_environmental_condition_ref() {
            return Err(format!("{path}: ENVIRONMENTAL_CONDITION_REF mismatch"));
        }
        let list_a = a.get_security_level_refs();
        let list_b = b.get_security_level_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SECURITY_LEVEL_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.SECURITY_LEVEL_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.SECURITY_LEVEL_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.SECURITY_LEVEL_REFS[{index}]"))?;
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_auth_role(
        &self,
        other: &Document,
        a: &DiagnosticAuthRole,
        b: &DiagnosticAuthRole,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        if a.get_bit_position() != b.get_bit_position() {
            return Err(format!("{path}: BIT_POSITION mismatch"));
        }
        if a.get_is_default() != b.get_is_default() {
            return Err(format!("{path}: IS_DEFAULT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_auth_role_proxy(
        &self,
        other: &Document,
        a: &DiagnosticAuthRoleProxy,
        b: &DiagnosticAuthRoleProxy,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        let list_a = a.get_authentication_role_refs();
        let list_b = b.get_authentication_role_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: AUTHENTICATION_ROLE_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.AUTHENTICATION_ROLE_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.AUTHENTICATION_ROLE_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.AUTHENTICATION_ROLE_REFS[{index}]"),
            )?;
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_security_level(
        &self,
        other: &Document,
        a: &DiagnosticSecurityLevel,
        b: &DiagnosticSecurityLevel,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_common_element(other, a.base(), b.base(), path)?;
        if a.get_access_data_record_size() != b.get_access_data_record_size() {
            return Err(format!("{path}: ACCESS_DATA_RECORD_SIZE mismatch"));
        }
        if a.get_key_size() != b.get_key_size() {
            return Err(format!("{path}: KEY_SIZE mismatch"));
        }
        if a.get_num_failed_security_access() != b.get_num_failed_security_access() {
            return Err(format!("{path}: NUM_FAILED_SECURITY_ACCESS mismatch"));
        }
        if a.get_security_delay_time() != b.get_security_delay_time() {
            return Err(format!("{path}: SECURITY_DELAY_TIME mismatch"));
        }
        if a.get_seed_size() != b.get_seed_size() {
            return Err(format!("{path}: SEED_SIZE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_session(
        &self,
        other: &Document,
        a: &DiagnosticSession,
        b: &DiagnosticSession,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_common_element(other, a.base(), b.base(), path)?;
        if a.get_id() != b.get_id() {
            return Err(format!("{path}: ID mismatch"));
        }
        if a.get_jump_to_boot_loader() != b.get_jump_to_boot_loader() {
            return Err(format!("{path}: JUMP_TO_BOOT_LOADER mismatch"));
        }
        if a.get_p2_server_max() != b.get_p2_server_max() {
            return Err(format!("{path}: P2_SERVER_MAX mismatch"));
        }
        if a.get_p2_star_server_max() != b.get_p2_star_server_max() {
            return Err(format!("{path}: P2_STAR_SERVER_MAX mismatch"));
        }
        Ok(())
    }
}
